BEGIN;
SET LOCAL search_path = public;

WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (700::BIGINT, 'El curso tiene potencial, pero no se siente que se aprovecha del todo. Se aprenden cosas valiosas para la vida laboral, pero el interés no lo es suficiente para que un estudiante tenga deseos de aprender. Eso si, se nota que el profe se esfuerza en mejorar el curso con cada semestre.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-07-18T00:00:00+00:00'::TIMESTAMPTZ, '107bc25cab7da5b82d3274476f7430bbf3851babef0c458f1a52321cf4649d95'::TEXT, ARRAY[2981]::BIGINT[]),
    (700::BIGINT, 'Asco de curso, asco de materia, asco de proyecto, asco todo lo relacionado a este curso que no sirve para nada. El profe como persona es buena gente, pero yo creo que aprendí mas en los cursos de ciencias sociales, que en esta cuecha. Modelados era la misma vara, pero al menos algo uno aprendía'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2026-05-29T00:00:00+00:00'::TIMESTAMPTZ, '166e68a1e6e2225666e2682cb1e6f7cbb3cdb0332559538f11b2183e188f9777'::TEXT, ARRAY[2981]::BIGINT[]),
    (700::BIGINT, 'Sus cursos siempre están muy actualizado. El profe sabe mucho y enseña cómo se trabaja en la vida real. Si uno muestra interés, él da mucha retroalimentación, se toma el tiempo de explicar y realmente ayuda a mejorar las habilidades técnicas y la forma de pensar como profesional. Súper recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Brinda apoyo']::TEXT[], '2026-02-11T00:00:00+00:00'::TIMESTAMPTZ, '2cdb3d411fa209d3b0f5e8b30e3badf6e8d50273df63979d1db6864e67f704d2'::TEXT, ARRAY[2981]::BIGINT[]),
    (700::BIGINT, 'Evidentemente sabe mucho, no obstante, por lo mismo sube el nivel de exigencia como si los estudiantes fuésemos profesionales en la industria. Esto tiene lo bueno y malo, por una parte se puede aprender mucho, pero no espere notas excelentes en todo porque básicamente el profe busca la perfección.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Pocos exámenes']::TEXT[], '2025-07-02T00:00:00+00:00'::TIMESTAMPTZ, '9057c2c0a3d709cc96451feb86dab9c82fbdd1c884ae9a2851dde7a3a0594f86'::TEXT, ARRAY[2981]::BIGINT[]),
    (700::BIGINT, 'El sigue dando el curso de espe, nada mas le añadió algunas cosas para ayudar a los de primer ingreso, clases cortas en general, temas interesantes pero confusos y toca aplicarlos para el proyecto, para el proyecto se necesitan varias reuniones semanales, consigabuengrupo, difcl q ponga buenas notas'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'b910f90a81b92c349d8e243dbdd79bf017b738614541d252306b1722566ff07f'::TEXT, ARRAY[2963]::BIGINT[]),
    (700::BIGINT, 'Sabe mucho de cómo se trabaja hoy en día y lo transmite a los estudiantes. Se nota que le interesa que los estudiantes aprendan. Muy buen profesor. El curso en sí es algo pesado por la cantidad de planeamientos que hay que hacer pero nada del otro mundo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases largas']::TEXT[], '2023-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'c0c30f33f3afac3eaacb88eec4353a330b78028272f90456385f6eab08aa8188'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Excelente profesor. Es buena nota y también tiene mucha experiencia en la industria que trata de plasmarla en los temas que se ven en el curso lo que le da mucho valor agregado. Es el curso más parecido a lo que uno se va a topa en la calle. Eso sí, puede ser bastante pesado por la cantidad de tarea'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Clases excelentes']::TEXT[], '2022-12-23T00:00:00+00:00'::TIMESTAMPTZ, 'c36ac3078dfac4dc643077f1eeb119d818b5fa52812c3f2f497423f29a275fe9'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'El curso me dejó muy confundido. La materia es interesante pero el profesor la hace muy confusa. Es orgulloso, le cuesta admitir cuando se equivoca y busca cualquier manera de evadir respuestas concretas cuando se le pregunta. Las calificaciones son arbitrarias y subjetivas. De lo peor de CE. -J'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-07-04T00:00:00+00:00'::TIMESTAMPTZ, '4993b8c261721ec0e6e6aa64ae68bbfca60d895e363947afe5f910af147ac9fd'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Es una excelente persona, muy buena nota en todo sentido. Suele tardar en entregar enunciados y notas, pero su principal interés es que uno disfrute el curso.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-07T00:00:00+00:00'::TIMESTAMPTZ, '7b8968362ddf86d9573cde914af5318ce34351a6b935aecc75b070b27e739620'::TEXT, ARRAY[2993]::BIGINT[]),
    (700::BIGINT, 'Es un muy buen profesor. Como SOA es una electiva, el profe busca que todos disfruten el curso y que no sea solo otra fuente de estrés. Las revisiones son largas por todos los consejos y retroalimentación que brinda. En lo personal, no me gustó mucho el taller que se realiza durante las clases.'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'b95072e0b8059d395a037ec855e8060a44b675173e459b8efb43d9f2a8cf8849'::TEXT, ARRAY[2993]::BIGINT[]),
    (700::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, '55e246d2c8e1fb0c47954f9f535e12ba6ac6e8fa1e7bf25b2e1c0de81d9ef707'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Es un curso DIFÍCIL , no se deben confiar. Se trabaja mucho pero hasta se disfruta. Las progras no son complejas pero si son largas.'::TEXT, 2.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Exámenes retadores']::TEXT[], '2019-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'e0301dc2062bc582be1fe02330f2edd63a362692386903f837ac07065a461754'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Es un profesor arrogante y agrandado , en una clase lo escuché decir de manera jactansiosa que los estudiantes que pasan con el con un 70'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-12-08T00:00:00+00:00'::TIMESTAMPTZ, '3384b1f7dad64521b49fea574a5a947249e995c358c088966a6f45ed059a8b91'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'El mejor profe. Excelente dando clases, justo calificando, intenta que el estudiante se sienta cómodo en clase y en todas las etapas del proyecto. Hay que estudiar para los exámenes por que son un 20% del curso y el proyecto es bastante largo. Es un curso que se trabaja bastante, pero se disfruta.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Inspirador']::TEXT[], '2018-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'df0e63b76c795ea6e9bc744b36e4bc7f2db1ad5b49c944945efc0716fcfc3647'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'De los mejores profesores que he tenido, explica muy bien los temas con buenos ejemplos, siempre esta disponible para ayudar y sabe bastante por la experiencia que tiene.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '287220e909a8b90741968ebfa9188f84114f96589c42a959c6a16dad258e43fd'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Siempre a la disposicion de los estudiantes para que aprendan al maximo, un curso duro pero muy bien trabajado y de los mejores que lleve. Aprendi mucho pues el brinda ejemplos en un contexto de la vida real y explica ejemplos programados de varios de los patrones de diseño que incluye en el curso'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'cdbf37cf46f1efcd271f2c94761cdb41deb55dd8a00f5487b98b4866157ad473'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Excelente profesor vale la pena llevar el curso con él. Eso si requiere invertir mucho tiempo en el curso no es nada facil pero con lo que se aprende vale la pena. Siempre esta dispuesto a ayudar al estudiante lo aconseja. Pero a como es buen profesor asi exige a sus estudiantes'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'fa6aed300682d4f8e77b7a98250f45c175750af2c8ea00df8ea5a7cc2434c69b'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'El profe enseña lo que realmente se ocupa en la calle, , es muy detallado a la hora de las revisiones, esta dispuesto a reunirse con los estudiantes las veces que sea necesario, y le gusta que los estudiantes hagan bien las cosas.'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '45b15b50e1e132a0b101df29a87c5acdfdab4a1a070bb2800a7dbc1ecb1f03e5'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Excelente profesor, el mejor que existe actualmente en la escuela'::TEXT, 2.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, '35b98e4f57cdb2eff716380327cd53730ed72322385f59f325313078ee9fdee8'::TEXT, ARRAY[2964]::BIGINT[]),
    (700::BIGINT, 'Hay que dedicarle mucho tiempo, o lo lamentarán a final de semestre. Es un profesor EXCELENTE, muy capacitado y comprometido con el curso y los estudiantes! ... el curso con él no es fácil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-17T00:00:00+00:00'::TIMESTAMPTZ, '8fc78c05be67979b93c15a9a4828be89fd7f954caed5b84f5f1439a3539cbb08'::TEXT, ARRAY[2964]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
